import sys
f=sys.argv[1]; s=open(f,encoding='utf-8').read()
def sub(a,b,n=1):
    global s; assert s.count(a)==n,(a[:90],s.count(a)); s=s.replace(a,b)
sub("'ผมพยายามนั่งตัวตรง จะรายงานตัว\\nแต่ลมไม่พอจะพูดสักคำ'","'ผมพยายามนั่งตัวตรง\\nไม่อยากให้คนเพิ่งมาถึงเห็นว่าผมลุกเองลำบาก'")
sub("'อาเหมยตอบแทนผม\\nผมนั่งอยู่ตรงนี้ ห่างไปสองก้าว เหมือนตู้ใบหนึ่ง'","'อาเหมยตอบแทนผม\\nเธอตอบถูกทุกข้อ','ผมนั่งอยู่ตรงนี้ แต่ไม่มีใครจำเป็นต้องหันมาทางผมเลย'")
sub("'\"ขอโทษครับคุณปู่ ผมควรถามคุณปู่เอง\"\\n\"อันสีฟ้าครับ ค่อยๆ\" เขาไม่ได้แย่งอันสีเขียวไปจากมือผม เขาแค่ยื่นอันสีฟ้ามา แล้วรอ']","'\"ขอโทษครับคุณปู่ ผมควรถามคุณปู่เอง\"','เขาช่วยผมหยิบยาพ่นสีฟ้า\\nไม่แย่งอันสีเขียวจากมือ แล้วรอให้พี่เฉินประเมิน']")
sub("await say('\"หายใจออกยาวๆ ทางปากนะครับ เหมือนเป่าเทียน ผมนับให้\"',{stay:1});","await say('เภสัชกรเฉินดูอาการผมหอบก่อน\\nเด็กคนนั้นอยู่ข้างๆ ไม่รีบบังคับให้ผมพูด',{stay:1});")
sub("await say(['\"ดีมากครับ ไม่ต้องรีบ เรามีเวลาทั้งบ่าย\"','เรามีเวลาทั้งบ่าย\\nไม่มีใครพูดประโยคนี้กับผมมานานแล้ว หมอมีให้ผมสามนาที']);","await say(['\"ไม่ต้องรีบครับ เราฟังอยู่\"','ผมมองหน้าเขา\\nเขายังอยู่ตรงนั้นจริงๆ','เราฟังอยู่\\nไม่ใช่ประโยคที่ผมได้ยินบ่อยนัก']);")
sub("'\"คุณปู่อนุญาตไหมครับ\"\\nเขาถาม ในห้องของผมเอง ว่าผมอนุญาตไหม'","'\"คุณปู่อนุญาตไหมครับ\"\\nผมมองไปรอบห้อง','นานแล้วที่ใครสักคนถามผมว่า อนุญาตไหม ในห้องของผมเอง'")
sub("'\"คุณปู่ครับ เรื่องที่คุณปู่เล่าให้ผมฟังวันนี้ ผมจะใช้เพื่อดูแลเรื่องยาเท่านั้น\\nถ้าจะต้องบอกใคร ผมจะถามคุณปู่ก่อนทุกครั้ง\"'","'\"เรื่องที่คุณปู่เล่า ผมไม่เอาไปพูดกับคนที่ไม่เกี่ยวข้องครับ\\nถ้าต้องแจ้งทีมรักษาเพื่อความปลอดภัย ผมจะบอกคุณปู่ก่อน\"'")
sub("['\"ไม่เป็นไรครับ งั้นเอาเรื่องเล็กที่สุดก่อน\\nถ้าพรุ่งนี้ทำได้หนึ่งอย่าง คุณปู่อยากทำอะไร\"','ผมมองเจ้าดำ\\nเด็กคนนั้นมองตาม แล้วยิ้ม']","['\"ไม่เป็นไรครับ\" เขาว่า\\n\"ถ้าพรุ่งนี้ดีขึ้นได้หนึ่งอย่าง คุณปู่อยากทำอะไรครับ\"','ผมมองเจ้าดำ\\nมันนอนทับสายจูงอยู่','เด็กคนนั้นมองตาม\\nแล้วนั่งเงียบ รอผมพูดต่อ']")
sub("['\"ภาระ\" เภสัชกรเฉินทวนคำนั้นช้าๆ\\n\"ปีที่แล้วคุณปู่ไปหาหมอเก้าสิบสามครั้ง ลงบันไดสี่ชั้นเองทุกครั้ง คนที่เป็นภาระ ทำแบบนั้นไม่ได้หรอกครับ\"','ผมไม่เคยมองเลขเก้าสิบสามแบบนั้นมาก่อน']","['\"ภาระ\" เภสัชกรเฉินทวนช้าๆ\\n\"คุณปู่พยายามทำเองมาตลอด แต่วันนี้ขอให้เราช่วยบ้างได้ไหมครับ\"','นั่นเป็นคำขอ ไม่ใช่คำสั่ง\\nผมยังไม่รู้ว่าต้องตอบยังไง']")
sub("['เด็กคนนั้นจดลงสมุด ตัวโต ขีดเส้นใต้สองเส้น\\n\"งั้นยาทุกตัวต่อจากนี้ ต้องตอบให้ได้ ว่ามันช่วยให้คุณปู่ลงบันไดสี่ชั้นหรือเปล่า\"']","['เด็กคนนั้นจดลงสมุด ตัวโต ขีดเส้นใต้สองเส้น','\"งั้นเราลองดูยาด้วยกันนะครับ ว่ามีอะไรที่ช่วยให้คุณปู่พาเจ้าดำลงไปเดินได้ปลอดภัยขึ้น\"']")
sub("['\"ได้ครับ\" เขาถอยมือกลับทันที\\nผมลองปฏิเสธดูเฉยๆ อยากรู้ว่าเขาจะหยุดจริงไหม','เขาหยุดจริง']","['\"ได้ครับ\" เขาถอยมือทันที\\nผมลองปฏิเสธดู อยากรู้ว่าเขาจะหยุดไหม','เขาหยุดจริง']")
sub("if(await YN()===1) await no('ผมหยิบยาพ่นสองอัน ส่งให้เขาเอง');","if(await YN()===1) await no('ผมหยิบยาพ่นสองอัน ส่งให้เขาเอง'); else await say(['เขารอให้ผมชี้ว่าตรงไหนดูได้\\nไม่หยิบอะไรเกินกว่านั้น']);")
sub("await say(['\"โต๊ะนี้ล่ะครับ\"']);\n  if(await YN()===1) await no('ผมเลื่อนกระติกน้ำออกเอง'); else await say(['เขาเลื่อนกระติกน้ำ\\nหม้อข้าวต้มอยู่ตรงนั้น ที่ที่ผมซ่อนมันไว้เมื่อเช้า']);",
    "await say(['\"โต๊ะนี้ล่ะครับ คุณปู่ให้ผมดูได้ไหม\"']);\n  if(await YN()===1) await no('ผมเลื่อนกระติกน้ำออกเอง');\n  await say(['หม้อข้าวต้มอยู่ตรงนั้น\\nที่ที่ผมซ่อนมันไว้เมื่อเช้า']);")
sub("ผมเป็นห่วงท้องคุณปู่\"\\nครูฝึกสอนผมว่าความร้อนฆ่าได้ทุกอย่าง ครูฝึกไม่ใช่เภสัชกร','\"ต้มหม้อเล็กลง พอกินวันต่อวัน ได้ไหมครับ วันที่ไม่ไหว เราจะลองถามเรื่องบริการส่งอาหารให้\"\\nเขาไม่ได้สั่งให้ผมเททิ้ง เขาถามผมว่า ได้ไหม'","ผมเป็นห่วงท้องคุณปู่\"','ครูฝึกสอนผมว่าความร้อนฆ่าได้ทุกอย่าง\\nครูฝึกไม่ใช่เภสัชกร','\"ต้มหม้อเล็กลง พอกินวันต่อวัน ได้ไหมครับ\\nวันที่ไม่ไหว เราจะลองถามเรื่องบริการส่งอาหารให้\"','เขาไม่ได้สั่งให้ผมเททิ้ง\\nเขาถามผมว่า ได้ไหม'")
sub("'\"ผมไม่บอกครับ ผมสัญญาไว้แล้ว\" เขาวางขวดคืนที่เดิม\\n\"ตัวนี้ไม่ได้ตีกับยาของคุณปู่ครับ แต่หลักฐานว่าช่วยเข่าได้มีไม่มาก และเดือนหนึ่งเท่ากับค่าข้าวหลายมื้อ\"'","'\"เรื่องนี้ผมจะคุยเท่าที่จำเป็นต่อการดูแล และจะบอกคุณปู่ก่อนครับ\" เขาวางขวดคืน','\"ขอจดส่วนประกอบไปตรวจนะครับ\\nผมยังบอกไม่ได้ว่ามันปลอดภัยกับยาทั้งหมดไหม\"','\"ส่วนหลักฐานว่าช่วยเข่าได้ ยังมีไม่มากครับ\"'")
open(f,'w',encoding='utf-8').write(s); print('d4a ok')
